#!/usr/bin/env node
/**
 * Brain Checkpoint Helper (generated by aqe init)
 *
 * Usage:
 *   node brain-checkpoint.cjs export   # Export brain to aqe.rvf (session-end)
 *   node brain-checkpoint.cjs verify   # Verify aqe.rvf exists (session-start)
 */
const { execFileSync } = require('child_process');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

// Resolve project root from __dirname (this file lives at <project>/.claude/helpers/)
// This works regardless of the current working directory
const PROJECT_ROOT = path.resolve(__dirname, '..', '..');
const AQE_DIR = path.join(PROJECT_ROOT, '.agentic-qe');
const RVF_PATH = path.join(AQE_DIR, 'aqe.rvf');
const DB_PATH = path.join(AQE_DIR, 'memory.db');
const MAX_AGE_HOURS = 24;
// #1238: an export the native RVF writer cannot hold fails the same way every
// turn. After one such failure, skip the Stop-hook export for this long, unless
// a newer aqe.rvf shows that a manual export has succeeded since.
const SKIP_PATH = path.join(AQE_DIR, 'brain-checkpoint.skip.json');
const RETRY_ENV = Number.parseFloat(process.env.AQE_BRAIN_CHECKPOINT_RETRY_HOURS || '');
const TOO_LARGE_RETRY_HOURS = Number.isFinite(RETRY_ENV) && RETRY_ENV >= 0 ? RETRY_ENV : 6;
// #1251: the export is compared with the published aqe.rvf and refused when a
// table collapsed (memory.db recreated from seed data, say). A deliberate shrink
// (`aqe learning prune --apply`, dream retention) leaves this acknowledgement
// with the row counts it left. The CLI honours it once, within 24h, and only
// while the brain still holds those counts; otherwise the hook drops it.
const SHRINK_ACK_PATH = path.join(AQE_DIR, 'brain-checkpoint.accept-shrink.json');
const SHRINK_ACK_MAX_AGE_HOURS = 24;
const MIRROR_REFUSAL = /RVF_MIRROR_(?:RICHER|INSPECTION_AMBIGUOUS):[^\n]*/;
const SHRINK_ACK_VERDICT = /SHRINK_ACK_(HONOURED|IGNORED): ([^\n]*)/;
// An older global aqe rejects the #1251 flags: back off rather than fail every turn.
const OUTDATED_CLI = /unknown option '(--(?:compare-with|richness-policy|accept-shrink))'/;
/**
 * How to run `aqe`. POSIX: the `aqe` binary. Windows (#872): never execFile
 * `aqe.cmd` (EINVAL without a shell since CVE-2024-27980, and a shell is unsafe);
 * reuse the hook shim's resolver, which finds the bundle and runs it via node.
 */
function aqeInvocation() {
  if (process.platform !== 'win32') return { cmd: process.env.AQE_HOOK_BIN || 'aqe', args: [] };
  const shimPath = path.join(__dirname, '..', 'hooks', 'aqe-hook.cjs');
  let src = '';
  try { src = fs.readFileSync(shimPath, 'utf8'); } catch { /* missing: handled below */ }
  // Only a #872+ shim may be required: an older one runs its hook main at load
  // time (spawn + process.exit(0)), which would kill this export silently.
  if (!src.includes('resolveAqeInvocation') || !src.includes('require.main === module')) {
    return { cmd: null, args: [], reason: '.claude/hooks/aqe-hook.cjs is missing or predates #872; re-run `aqe init`' };
  }
  try {
    return require(shimPath).resolveAqeInvocation({ project: PROJECT_ROOT });
  } catch (e) {
    return { cmd: null, args: [], reason: 'aqe-hook.cjs failed to load: ' + e.message };
  }
}

// Mount-local kill switch. `brain export` (below) spawns a native RVF writer
// that, on a macOS Docker virtiofs bind mount, deadlocks in a futex and IGNORES
// the SIGTERM that execFileSync's timeout sends — so the 60s timeout can't reap
// it and orphaned exporters pile up (~1.5GB RSS observed 2026-07-08). Disable
// via env `AQE_DISABLE_BRAIN_CHECKPOINT=1` or a `.agentic-qe/DISABLE_BRAIN_CHECKPOINT`
// marker file. Opt-in: shipped installs without the flag behave exactly as before.
const CHECKPOINT_DISABLED =
  process.env.AQE_DISABLE_BRAIN_CHECKPOINT === '1' ||
  fs.existsSync(path.join(AQE_DIR, 'DISABLE_BRAIN_CHECKPOINT'));

function log(msg) { process.stderr.write('[brain-checkpoint] ' + msg + '\n'); }

/** A repository can commit `.agentic-qe` as a symlink: only write into a REAL dir. */
function isRealDir(dir) {
  try { const st = fs.lstatSync(dir); return st.isDirectory() && !st.isSymbolicLink(); } catch { return false; }
}

/**
 * Remove whatever sits at `p` WITHOUT following it: unlink drops a planted
 * symlink itself (even a dangling one, which existsSync reports as absent),
 * so the exporter below creates a fresh regular file instead of writing
 * through the link.
 */
function removeEntry(p) {
  try { fs.unlinkSync(p); } catch (e) { if (!e || e.code !== 'ENOENT') throw e; }
}

/**
 * The skip marker left by a too-large export, or null once it has expired or
 * a newer aqe.rvf shows that an export has succeeded since.
 */
function activeSkip() {
  let st;
  try { st = fs.lstatSync(SKIP_PATH); } catch { return null; }
  let skip = null;
  if (st.isFile()) { try { skip = JSON.parse(fs.readFileSync(SKIP_PATH, 'utf8')); } catch { /* unreadable */ } }
  const at = skip ? Date.parse(skip.at) : NaN;
  let rvfMtime = 0;
  try { rvfMtime = fs.lstatSync(RVF_PATH).mtimeMs; } catch { /* absent */ }
  if (!Number.isFinite(at) || Date.now() >= at + TOO_LARGE_RETRY_HOURS * 3600000 || rvfMtime > at) {
    try { removeEntry(SKIP_PATH); } catch { /* best-effort */ }
    return null;
  }
  return skip;
}

function dropShrinkAck(why) {
  try { removeEntry(SHRINK_ACK_PATH); } catch { /* best-effort */ }
  log('Ignored the shrink acknowledgement (' + why + '); the normal checkpoint policy applies.');
}

/**
 * The acknowledgement of a deliberate shrink, or null. One that is unreadable,
 * over 24h old, or older than aqe.rvf (already checkpointed) is dropped. The
 * CLI checks the counts it records against the export (--accept-shrink).
 */
function pendingShrinkAck() {
  let st;
  try { st = fs.lstatSync(SHRINK_ACK_PATH); } catch { return null; }
  let ack = null;
  if (st.isFile()) { try { ack = JSON.parse(fs.readFileSync(SHRINK_ACK_PATH, 'utf8')); } catch { /* unreadable */ } }
  const at = ack ? Date.parse(ack.at) : NaN;
  let rvfMtime = 0;
  try { rvfMtime = fs.lstatSync(RVF_PATH).mtimeMs; } catch { /* absent */ }
  let why = null;
  if (!Number.isFinite(at)) why = 'unreadable';
  else if (Date.now() - at > SHRINK_ACK_MAX_AGE_HOURS * 3600000) why = 'older than 24h';
  else if (rvfMtime > at) why = 'already checkpointed';
  if (why) { dropShrinkAck(why); return null; }
  return { at, producer: String(ack.producer) };
}

/** Act on the CLI's verdict on the acknowledgement; returns its producer when honoured. */
function settleShrinkAck(output) {
  const verdict = String(output || '').match(SHRINK_ACK_VERDICT);
  if (!verdict) return null; // no verdict (the export failed first): keep it for the next turn
  if (verdict[1] === 'IGNORED') { dropShrinkAck(verdict[2].trim()); return null; }
  return verdict[2].trim();
}

/** How to end a back-off now, for the session-start report. */
function resumeHint(skip) {
  return MIRROR_REFUSAL.test(skip.reason)
    ? 'To resume now, back up aqe.rvf and run `aqe brain export -o .agentic-qe/aqe.rvf --force-overwrite-richer`, '
      + 'or delete .agentic-qe/brain-checkpoint.skip.json to retry.'
    : skip.reason.includes('upgrade to enable the checkpoint guard')
      ? 'Upgrade the global aqe (npm i -g agentic-qe), then delete .agentic-qe/brain-checkpoint.skip.json.'
      : 'To retry now, delete .agentic-qe/brain-checkpoint.skip.json.';
}

function writeSkip(reason) {
  const at = new Date();
  const skip = {
    reason,
    at: at.toISOString(),
    retryAfter: new Date(at.getTime() + TOO_LARGE_RETRY_HOURS * 3600000).toISOString(),
  };
  // 'wx' after unlink: never write through a planted symlink (#970).
  try { removeEntry(SKIP_PATH); fs.writeFileSync(SKIP_PATH, JSON.stringify(skip) + '\n', { flag: 'wx' }); } catch { /* best-effort */ }
  return skip;
}

// The export is written to a temp store next to aqe.rvf and renamed over it
// only once it succeeded, so a failed, too-large or killed export keeps the
// previous checkpoint. The CLI writes these sidecars next to its -o path.
const RVF_SIDECARS = ['.idmap.json', '.manifest.json'];
const TMP_PREFIX = path.basename(RVF_PATH) + '.tmp-';

function isPidAlive(pid) {
  try { process.kill(pid, 0); return true; } catch (e) { return !!e && e.code === 'EPERM'; }
}

/** Remove entries in .agentic-qe that start with `prefix` (unlink: never follows a symlink). */
function removeByPrefix(prefix, keep) {
  let entries = [];
  try { entries = fs.readdirSync(AQE_DIR); } catch { return; }
  for (const entry of entries) {
    if (!entry.startsWith(prefix) || (keep && keep(entry))) continue;
    try { removeEntry(path.join(AQE_DIR, entry)); } catch { /* best-effort: a leftover tmp is inert */ }
  }
}

/** Temp stores of earlier hook runs that were killed: their owning pid is gone. */
function sweepStaleTmp() {
  removeByPrefix(TMP_PREFIX, (entry) => {
    const pid = Number.parseInt(entry.slice(TMP_PREFIX.length).split('-')[0], 10);
    return !Number.isInteger(pid) || pid <= 0 || isPidAlive(pid);
  });
}

function lexists(p) {
  try { fs.lstatSync(p); return true; } catch { return false; }
}

/**
 * Promote a completed temp store over aqe.rvf. rename() replaces whatever
 * sits at the destination, a planted symlink included, without writing
 * through it (#970).
 *
 * The store goes first, then the sidecars: until the store rename succeeds
 * nothing has changed, so a failure there leaves the old store with its own
 * idmap. If a sidecar rename fails after that, the stale destination sidecar
 * is removed, so the new store is never read with the previous export's
 * idmap. A store without an idmap is consistent; one with another export's
 * idmap is not.
 */
function promote(tmp) {
  fs.renameSync(tmp, RVF_PATH);
  for (const suffix of RVF_SIDECARS) {
    try {
      if (lexists(tmp + suffix)) fs.renameSync(tmp + suffix, RVF_PATH + suffix);
      else removeEntry(RVF_PATH + suffix);
    } catch {
      try { removeEntry(RVF_PATH + suffix); } catch { /* best-effort */ }
    }
  }
}

/** `aqe --version` of the installed CLI, for the outdated-CLI back-off. */
function aqeVersion(aqe) {
  try {
    const out = execFileSync(aqe.cmd, [...aqe.args, '--version'],
      { timeout: 10000, encoding: 'utf-8', windowsHide: true, stdio: ['ignore', 'pipe', 'ignore'] });
    return out.trim().split(/\s+/).pop() || 'unknown';
  } catch {
    return 'unknown';
  }
}

function exportBrain() {
  if (!fs.existsSync(DB_PATH)) { log('No memory.db, skipping'); return { exported: false }; }
  if (!isRealDir(AQE_DIR)) {
    const reason = '.agentic-qe is a symlink; refusing to write through it';
    log('Export skipped: ' + reason); return { exported: false, reason };
  }
  const ack = pendingShrinkAck();
  const skip = activeSkip();
  // A shrink acknowledged after the back-off began is the answer to it.
  if (skip && !(ack && ack.at > Date.parse(skip.at))) {
    // Logged once, when the back-off began; session-start verify reports it.
    return { exported: false, skipped: true, reason: skip.reason, retryAfter: skip.retryAfter };
  }
  const aqe = aqeInvocation();
  if (!aqe.cmd) { log('Export skipped: ' + aqe.reason); return { exported: false, reason: aqe.reason }; }
  sweepStaleTmp();
  const tmp = path.join(AQE_DIR, TMP_PREFIX + process.pid + '-' + crypto.randomBytes(4).toString('hex'));
  try {
    // The name is fresh, but drop anything already there without following it.
    for (const suffix of ['', ...RVF_SIDECARS]) removeEntry(tmp + suffix);
    const args = [...aqe.args, 'brain', 'export', '-o', tmp, '--format', 'rvf'];
    if (lexists(RVF_PATH)) args.push('--compare-with', RVF_PATH, '--richness-policy', 'checkpoint');
    if (ack) args.push('--accept-shrink', SHRINK_ACK_PATH);
    const result = execFileSync(
      aqe.cmd, args,
      { timeout: 60000, encoding: 'utf-8', windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] }
    );
    // A zero exit without a store is a failure, not an empty checkpoint.
    if (!lexists(tmp)) throw new Error('brain export exited 0 but wrote no store');
    promote(tmp);
    const m = result.match(/Patterns:\s+(\d+)/);
    const p = m ? m[1] : '0';
    log('Exported ' + p + ' patterns to aqe.rvf');
    const accepted = ack ? settleShrinkAck(result) : null;
    if (!accepted) return { exported: true, patterns: parseInt(p) };
    try { removeEntry(SHRINK_ACK_PATH); removeEntry(SKIP_PATH); } catch { /* spent: older than aqe.rvf now */ }
    log('Accepted the smaller brain (' + accepted + ')');
    return { exported: true, patterns: parseInt(p), acceptedShrink: accepted };
  } catch (e) {
    const output = String(e.stderr || '') + String(e.stdout || '');
    if (ack) settleShrinkAck(e.stdout);
    const outdated = output.match(OUTDATED_CLI);
    if (outdated) {
      const skip = writeSkip('installed aqe ' + aqeVersion(aqe) + ' lacks ' + outdated[1] + '; upgrade to enable the checkpoint guard');
      log('Export skipped, previous aqe.rvf kept: ' + skip.reason);
      log('Skipping the checkpoint export until ' + skip.retryAfter + ' (logged once).');
      return { exported: false, outdatedCli: true, reason: skip.reason, retryAfter: skip.retryAfter };
    }
    const refused = output.match(MIRROR_REFUSAL);
    if (refused) {
      const skip = writeSkip(refused[0].trim());
      log('Export refused, previous aqe.rvf kept: ' + skip.reason);
      log('Skipping the checkpoint export until ' + skip.retryAfter + ' (logged once). If the smaller brain is '
        + 'intended, back up aqe.rvf and run: aqe brain export -o .agentic-qe/aqe.rvf --force-overwrite-richer');
      return { exported: false, richer: true, reason: skip.reason, retryAfter: skip.retryAfter };
    }
    const tooLarge = output.match(/RVF_KERNEL_TOO_LARGE:[^\n]*/);
    if (tooLarge) {
      const skip = writeSkip(tooLarge[0].trim());
      log('Export failed: ' + skip.reason);
      log('Skipping the checkpoint export until ' + skip.retryAfter + ' (AQE_BRAIN_CHECKPOINT_RETRY_HOURS sets the wait).');
      return { exported: false, tooLarge: true, reason: skip.reason, retryAfter: skip.retryAfter };
    }
    log('Export failed: ' + e.message + ' (previous aqe.rvf kept)');
    return { exported: false, reason: e.message };
  } finally {
    // The temp store, its sidecars and the CLI's own tmp files under it.
    removeByPrefix(path.basename(tmp));
  }
}

function verifyBrain() {
  if (!fs.existsSync(RVF_PATH)) {
    const skip = activeSkip();
    if (skip) {
      log('No aqe.rvf found; checkpoint export paused until ' + skip.retryAfter + ': ' + skip.reason + ' ' + resumeHint(skip));
      return { valid: false, reason: 'missing', skippedUntil: skip.retryAfter, resumeHint: resumeHint(skip) };
    }
    log('No aqe.rvf found');
    return { valid: false, reason: 'missing' };
  }
  const stat = fs.statSync(RVF_PATH);
  const paused = activeSkip();
  if (paused) log('Checkpoint export paused until ' + paused.retryAfter + ': ' + paused.reason + ' ' + resumeHint(paused));
  const pause = paused
    ? { pausedUntil: paused.retryAfter, pauseReason: paused.reason, resumeHint: resumeHint(paused) }
    : {};
  const ageH = (Date.now() - stat.mtimeMs) / 3600000;
  if (stat.size < 1024) { log('aqe.rvf too small'); return { valid: false, reason: 'too-small', ...pause }; }
  if (ageH > MAX_AGE_HOURS) { log('aqe.rvf is ' + ageH.toFixed(1) + 'h old'); return { valid: true, stale: true, ...pause }; }
  log('aqe.rvf OK (' + (stat.size/1048576).toFixed(1) + ' MB)');
  return { valid: true, stale: false, ...pause };
}

const cmd = process.argv[2] || 'verify';
let result;
if (CHECKPOINT_DISABLED) {
  result = { disabled: true, reason: 'brain-checkpoint disabled on this mount' };
} else {
  result = cmd === 'export' ? exportBrain() : verifyBrain();
}
if (process.argv.includes('--json')) process.stdout.write(JSON.stringify(result));
